create or replace function public.istek_kapisi()
returns void language plpgsql stable set search_path = '' as $$
declare
  yol text := lower(coalesce(current_setting('request.path', true), ''));
begin
  if yol = '/spatial_ref_sys' or yol like '/spatial_ref_sys/%' then
    raise exception 'Bu kaynak kapali' using errcode = '42501';
  end if;
end
$$;
revoke all on function public.istek_kapisi() from public;
grant execute on function public.istek_kapisi() to anon, authenticated, service_role;
do $$
declare sonuc text := '';
begin
  perform set_config('request.path', '/ifadeler', true);
  perform public.istek_kapisi(); sonuc := sonuc || 'ifadeler=gecti ';
  perform set_config('request.path', '/rpc/profil_karti', true);
  perform public.istek_kapisi(); sonuc := sonuc || 'rpc=gecti ';
  perform set_config('request.path', '', true);
  perform public.istek_kapisi(); sonuc := sonuc || 'bos=gecti ';
  begin
    perform set_config('request.path', '/spatial_ref_sys', true);
    perform public.istek_kapisi(); sonuc := sonuc || 'srs=GECTI(HATA) ';
  exception when insufficient_privilege then sonuc := sonuc || 'srs=reddedildi';
  end;
  raise notice '%', sonuc;
  create temp table if not exists _k(s text); delete from _k; insert into _k values (sonuc);
end $$;
select s from _k;

