                    onPress={() => setMekan(null)}
                    hitSlop={10}
                    accessibilityRole="button"
                    accessibilityLabel={t('hikaye.mekanKaldir')}
                    testID="hikaye-mekan-kaldir"
                  >
                    <Text style={stiller.mekanCipKapat}>×</Text>
                  </Pressable>
                </View>
