 (select string_agg(conname||' '||pg_get_constraintdef(oid), '; ') from pg_constraint where conrelid='public.hikaye_goruntulemeler'::regclass) kisitlar,
 (select string_agg(conname||' '||pg_get_constraintdef(oid), '; ') from pg_constraint where conrelid='public.ifadeler'::regclass and contype='p') ifade_pk;

