  insert into public.hikaye_goruntulemeler (hikaye_id, kullanici_id, ifade)
  values (p_hikaye_id, auth.uid(), p_ifade)
  on conflict (hikaye_id, kullanici_id) do update set ifade = excluded.ifade;
end;
