{"id":"bfa511a1-8487-442c-8efa-053fe5e6d90f","slug":"hesap-sil","name":"hesap-sil","status":"ACTIVE","version":7,"created_at":1787408948088,"updated_at":1789294249785,"verify_jwt":true,"import_map":false,"entrypoint_path":"/tmp/user_fn_swpiibyuoffykbmirvgq_bfa511a1-8487-442c-8efa-053fe5e6d90f_7/source/index.ts","ezbr_sha256":"51f148bc29accaeec8edac2cf7556eee75753ad924330daa752fe1229d9c7a1d","files":[{"name":"index.ts","content":"// Hesap silme (spec karar 67, 68). auth.users satirini silmek Admin API
// gerektiriyor, bu yuzden Edge Function.
//
// Akis:
//   1) Cagiranin JWT'si dogrulanir - KENDI hesabindan baskasini silemez;
//      kimlik VE telefon buradan cikar.
//   2) IKI KAPIDAN BIRI, SUNUCUDA zorlanir, istemci atlayamaz:
//      (a) ASIL YOL (2026-09-13): parola YOKSA cagiranin son girisi
//          TAZE olmali (`girisTazeMi`, 10 dk) - ekranlar silmeden hemen
//          once e-posta ONAY KODUYLA (`verifyOtp`) ya da Apple/Google
//          ile yeniden giris yaptiriyor. Kullanicinin karari: "e-postaya
//          gelen onay kodunu giren biri hesabini silebilecek".
//      (b) ESKI YOL: govdeden parola gelirse `signInWithPassword` ile
//          dogrulanir. Ekranlar artik gondermiyor; canli test betikleri
//          ve eski istemciler icin duruyor.
//   3) Silinecek Storage yollari TOPLANIR (henuz silinmez).
//   4) auth.admin.deleteUser cagrilir; cascade kalani goturur.
//   5) (4) basariliysa Storage'daki profil ve check-in fotograflari
//      silinir.
//
// (3) NEDEN (4)'TEN ONCE: kullanici satiri gidince check_inler de
// cascade ile gider ve fotograf yollarini bir daha okuyamayiz. Yollar
// once toplanmali.
//
// (5) NEDEN (4)'TEN SONRA: `deleteUser` basarisiz olursa kullanici hata
// gorur, hesap DURUYOR ama fotograflari zaten kalici silinmis olurdu.
// Storage silme yalnizca `deleteUser` basarili DONDUKTEN SONRA calisiyor.
//
// DEPLOY NOTU: `verify_jwt` ACIK olmali. Cagriyi gercek bir kullanici
// yapiyor ve yetkilendirmenin tamami onun JWT'sine dayaniyor.
//
// CORS: bu uc nokta web'de tarayicidan cagriliyor; OPTIONS preflight ve
// gercek yanitlara CORS basliklari ekli.
//
// LOG: parola, telefon ya da mesaj icerigi YAZILMAZ; yalnizca islem
// sonucu ve silinen/elenen dosya sayilari. Govde de loglanmaz.

import { createClient, type SupabaseClient } from 'npm:@supabase/supabase-js@2'
import { fotografYollari, girisTazeMi } from './saf.ts'

// Bucket kimlikleri migrasyonlardan BIREBIR: check-in bucket'inin gercek
// id'si TIRELI ('check-in-fotograflari').
const PROFIL_BUCKET = 'profil-fotograflari'
const CHECKIN_BUCKET = 'check-in-fotograflari'

const CORS_BASLIKLARI: Record<string, string> = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

function yanit(govde: unknown, durum: number): Response {
  return new Response(JSON.stringify(govde), {
    status: durum,
    headers: { 'Content-Type': 'application/json', ...CORS_BASLIKLARI },
  })
}

Deno.serve(async (istek: Request) => {
  if (istek.method === 'OPTIONS') {
    return new Response(null, { status: 204, headers: CORS_BASLIKLARI })
  }

  if (istek.method !== 'POST') {
    return yanit({ hata: 'Yalnizca POST' }, 405)
  }

  const yetkiBasligi = istek.headers.get('Authorization')
  if (!yetkiBasligi) {
    return yanit({ hata: 'Kimlik dogrulamasi gerekli' }, 401)
  }

  const url = Deno.env.get('SUPABASE_URL')
  const servisAnahtari = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')
  const anonAnahtari = Deno.env.get('SUPABASE_ANON_KEY')
  if (!url || !servisAnahtari || !anonAnahtari) {
    console.error('hesap-sil: ortam degiskenleri eksik')
    return yanit({ hata: 'Sunucu yapilandirmasi eksik' }, 500)
  }

  const yonetici = createClient(url, servisAnahtari, {
    auth: { persistSession: false, autoRefreshToken: false },
  })

  // 1) Cagiran kim? Jeton service-role istemcisiyle dogrulaniyor. Govdeden
  // gelen bir kimlige ASLA guvenilmiyor - silinecek hesap yalnizca JWT'den
  // cikan kimlik. Ayni kayittan `last_sign_in_at` de okunuyor - (2a).
  const jeton = yetkiBasligi.replace(/^Bearer\s+/i, '')
  const { data: kullaniciVerisi, error: kullaniciHata } =
    await yonetici.auth.getUser(jeton)
  const kimlik = kullaniciVerisi?.user?.id
  const eposta = kullaniciVerisi?.user?.email
  const telefon = kullaniciVerisi?.user?.phone
  if (kullaniciHata || !kimlik) {
    return yanit({ hata: 'Kimlik dogrulamasi gecersiz' }, 401)
  }

  // 2) Kapi: taze giris YA DA parola - SUNUCUDA zorlanir, istemci
  // atlayamaz.
  let parola: string | null = null
  try {
    const govde = await istek.json()
    parola = typeof govde?.parola === 'string' ? govde.parola : null
  } catch {
    parola = null
  }

  if (!parola || parola.length === 0) {
    // (a) TAZE GIRIS. `getUser` GoTrue'dan kullanicinin GUNCEL kaydini
    // getiriyor (JWT'deki eski kopyayi degil); `last_sign_in_at` son
    // GERCEK giristir - e-posta kodu, Apple/Google ya da parola girisi.
    // Jeton yenileme bu alani ilerletmez. Sinir `TAZELIK_DAKIKA`.
    if (!girisTazeMi(kullaniciVerisi?.user?.last_sign_in_at)) {
      console.error('hesap-sil: parola yok ve giris taze degil', { kimlik })
      return yanit({ hata: 'Onay gerekli: parolani yaz ya da yeniden dogrula' }, 403)
    }
    return await sil(yonetici, kimlik)
  }

  if (!eposta && !telefon) {
    return yanit({ hata: 'Bu hesap parola ile dogrulanamiyor' }, 400)
  }

